export const stripMarkdown = (text) => {
    if (!text)
        return null;
    return (text
        // Remove images: ![alt](url) → (empty) - handles nested parentheses in URLs
        .replace(/!\[([^\]]*)\]\([^()]*(?:\([^()]*\)[^()]*)*\)/g, '')
        // Remove reference images: ![alt][ref] → (empty)
        .replace(/!\[([^\]]*)\]\[[^\]]*\]/g, '')
        // Remove links: [text](url) → text - handles nested parentheses in URLs and empty text
        .replace(/\[([^\]]*)\]\([^()]*(?:\([^()]*\)[^()]*)*\)/g, '$1')
        // Remove reference links: [text][ref] → text (also handles empty text)
        .replace(/\[([^\]]*)\]\[[^\]]*\]/g, '$1')
        // Remove bold+italic: ***text*** or ___text___ → text
        .replace(/\*{3}([^*]+)\*{3}/g, '$1')
        .replace(/_{3}([^_]+)_{3}/g, '$1')
        // Remove bold: **text** or __text__ → text
        .replace(/\*{2}([^*]+)\*{2}/g, '$1')
        .replace(/_{2}([^_]+)_{2}/g, '$1')
        // Remove italic: *text* or _text_ → text
        .replace(/\*([^*]+)\*/g, '$1')
        .replace(/(?<!\w)_([^_]+)_(?!\w)/g, '$1')
        // Remove code: ```code```, ``code``, `code` → code (order matters)
        .replace(/`{3}([^`]+)`{3}/g, '$1')
        .replace(/`{2}([^`]+)`{2}/g, '$1')
        .replace(/`([^`]+)`/g, '$1')
        // Remove strikethrough: ~~text~~ → text
        .replace(/~~([^~]+)~~/g, '$1')
        // Remove HTML tags (only valid tags starting with letter, not angle brackets in text)
        .replace(/<\/?[a-zA-Z][^>]*>/g, '')
        // Normalize whitespace
        .replace(/\s+/g, ' ')
        .trim());
};
